-- Enums · Estados y resultados compartidos cliente/servidor (S1)
-- La FSM es POR JUGADOR (plan §4): nunca existe un estado global de ronda.
local Enums = {
	DeliveryState = {
		Idle = "IDLE",
		Offer = "OFFER",
		Reveal = "REVEAL",
		Carry = "CARRY",
		Resolve = "RESOLVE",
		Payout = "PAYOUT",
	},
	DeliveryResult = {
		Success = "SUCCESS",
		Timeout = "TIMEOUT", -- se acabó el tiempo
		Exploded = "EXPLODED", -- Explosive llegó a 0 de estabilidad
		Broken = "BROKEN", -- paquete roto (Fragile, V2)
		Dropped = "DROPPED", -- paquete soltado
	},
}

return Enums

-- Destinations · Catálogo de destinos del MVP (GDD §40: 3 destinos).
-- La POSICIÓN real no se hardcodea aquí: cada destino tendrá un Part con el mismo
-- id en Workspace.Delivery60.Destinations (lo crea cmd_000022 junto a la ciudad) y
-- el DestinationRegistry lo resolverá en runtime. La distancia se MEDIRÁ sobre la
-- ciudad real (plan §9-3: bandas de 25/35/45 s a velocidad base, nunca estimadas).
local Destinations = {
	House_1 = {
		id = "House_1",
		displayName = "House #1",
		zone = "West",
		timeBandSeconds = 25, -- banda corta [A MEDIR sobre la ciudad real]
	},
	House_2 = {
		id = "House_2",
		displayName = "House #2",
		zone = "Center",
		timeBandSeconds = 35, -- [A MEDIR]
	},
	House_3 = {
		id = "House_3",
		displayName = "House #3",
		zone = "East",
		timeBandSeconds = 45, -- banda larga [A MEDIR]
	},
}

return Destinations
